import sympy

def count_pairs(n):
    g = 2023
    L = sympy.factorial(n)
    if L % g != 0:
        return 0
    N = L // g
    return 2**sympy.primeomega(N)

results = []
for n in range(1, 50):
    results.append((n, count_pairs(n)))

for n, count in results:
    if count <= 4000:
        print(f"n={n}, count={count}")
    else:
        print(f"n={n}, count={count} (too many)")

